<head>
<meta charset="utf-8">
<title>Neural Circuit Architecture Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  :root {
    --bg-deep: #060d18;
    --bg-navy: #0a1628;
    --bg-section: #0f1f38;
    --bg-card: #132744;
    --accent-blue: #0096c7;
    --accent-teal: #00b894;
    --accent-gold: #f0a500;
    --accent-light-blue: #48cae4;
    --text-primary: #ffffff;
    --text-secondary: #c8d6e5;
    --text-muted: #8395a7;
    --border-subtle: rgba(72, 202, 228, 0.2);
    --border-gold: rgba(240, 165, 0, 0.3);
    --width: 3179px;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #000;
    display: flex;
    justify-content: center;
    font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    -webkit-font-smoothing: antialiased;
  }

  .poster {
    width: var(--width);
    background: linear-gradient(180deg, #060d18 0%, #0a1628 5%, #0a1628 100%);
    color: var(--text-primary);
    position: relative;
    overflow: hidden;
  }

  /* Ambient background effects */
  .poster::before {
    content: '';
    position: absolute;
    top: -200px; right: -200px;
    width: 1200px; height: 1200px;
    background: radial-gradient(circle, rgba(0, 150, 199, 0.06) 0%, transparent 70%);
    pointer-events: none;
  }
  .poster::after {
    content: '';
    position: absolute;
    bottom: 800px; left: -300px;
    width: 1000px; height: 1000px;
    background: radial-gradient(circle, rgba(0, 184, 148, 0.05) 0%, transparent 70%);
    pointer-events: none;
  }

  /* ---- HEADER ---- */
  .header {
    position: relative;
    padding: 80px 120px 60px;
    text-align: center;
