  .metric-card .metric-icon {
    font-size: 48px;
    margin-bottom: 16px;
    opacity: 0.9;
  }
  .metric-value {
    font-size: 68px;
    font-weight: 900;
    letter-spacing: -0.02em;
    line-height: 1.1;
    margin-bottom: 12px;
  }
  .metric-card:nth-child(1) .metric-value { color: var(--accent-light-blue); }
  .metric-card:nth-child(2) .metric-value { color: var(--accent-teal); }
