const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();

  // A0 portrait: 841mm x 1189mm, render at ~2x screen density
  const posterWidth = 3179;
  await page.setViewport({ width: posterWidth, height: 1000, deviceScaleFactor: 1 });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Get full page height
  const bodyHandle = await page.$('.poster');
  const { height } = await bodyHandle.boundingBox();

  // Set viewport to full poster height
  await page.setViewport({ width: posterWidth, height: Math.ceil(height), deviceScaleFactor: 1 });

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    clip: { x: 0, y: 0, width: posterWidth, height: Math.ceil(height) }
  });

  await browser.close();
  console.log('Poster rendered to /app/output/final_poster.png (' + posterWidth + 'x' + Math.ceil(height) + ')');
})();

